add(nr=25, id="10636636782858", orig_titel="Miniband Latex 5 pack ink påse",
 fakta="Miniband Latex 5 pack ink påse. Korta latexband, korta gummiband, motståndsband, miniband. Dessa gummiband säljs i paket om fem och kommer med en påse. Alla gummibanden har olika tjocklek och är i olika färger samt är märkta med respektive motstånd. Den här produkten finns att se på plats i vårt showroom. Övrig information: Olika färger för enkelt val av rätt motstånd. Omkretsen för samtliga är 60cm. Grön = Light(ca 4,5kg). Blå = Medium(ca 6,8kg). Gul = Heavy(ca 9kg). Röd = X-Heavy(ca 13,5kg). Svart = XX-Heavy(ca 18kg). Material: Latex. Omkrets: 60cm. Bredd: 5cm. Träningsråd och fördelar med motståndsband. Märke Gorilla Sports Norden",
 titel="Miniband latex, set med 5 band och påse",
 seo_title="Miniband latex, set med 5 band och påse",
 meta="Miniband i latex, ett set med fem korta gummiband i olika färger och motstånd, från ca 4,5 till ca 18 kg. Omkrets 60 cm, bredd 5 cm. Förvaringspåse ingår.",
 intro="Miniband är korta motståndsband i latex. Setet har fem band med olika tjocklek, färg och motstånd, och en påse för förvaring.",
 passar=["Dig som vill träna med korta motståndsband hemma","Dig som vill kunna välja mellan fem motståndsnivåer"],
 spec=["Motstånd: grön ca 4,5 kg (light), blå ca 6,8 kg (medium), gul ca 9 kg (heavy), röd ca 13,5 kg (x-heavy), svart ca 18 kg (xx-heavy)","Förvaring: påse medföljer","Omkrets: 60 cm","Bredd: 5 cm","Material: latex","Set: 5 band"],
 faq=[("Hur vet jag vilket motstånd ett band har?","Banden har olika färg och är märkta med respektive motstånd.")], marke=None,
 motivering="Fakta ur källan. Träningsråd, fördelslistan och påståenden som \"hudvänligt\", \"effektiv träning\" och \"bäst\" utelämnas. Showroom-raden (Gorillas adress) utelämnas.",
 att_bekrafta=["Motståndsvärdena är källans \"ca\"-uppgifter i kg. Hur de är uppmätta framgår inte.","Showroom-uppgiften hör till Gorilla Sports och är bortagen från BOS-texten."])

