add(nr=29, id="10470922682634", orig_titel="Barnhjälm MELON Real Melon",
 fakta="Barnhjälm MELON Real Melon. The Melon Real Melon helmet. This children's helmet with a watermelon design is specially designed for children aged 3 to 7 years. The helmet comes with three different thicknesses of cushioning, allowing the helmet to grow with your child. The Fidlock magnetic fastening allows the helmet to be opened and fastened with one hand, and the MACS system with 12 air vents ensures adequate ventilation even on hot days. A Spin Dial roller on the back of the helmet allows you to adjust the helmet to fit your child's head precisely. Made by Melon (Germany). Product Details: Size: XXS/S: 46-52 cm (3 to 7 years old). Fastening: Fidlock magnetic fastening. Ventilation: 12 air vents. Weight: under 300 g. Adjustment: Spin Dial roller. Materials: polycarbonate outer shell, EPS inner shell. Optional accessories: optional winter cover. The integrated CoolMax cushioning inside the helmet is comfortable and hygienic and can withstand 30 degree machine washing. Märke Melon",
 titel="Barnhjälm Melon Real Melon, XXS/S, 46–52 cm",
 seo_title="Barnhjälm Melon Real Melon, XXS/S, 46–52 cm",
 meta="Melon Real Melon är en barnhjälm med vattenmelonmönster för barn 3–7 år, XXS/S, 46–52 cm. Fidlock-spänne, 12 ventilationsöppningar och Spin Dial.",
 intro="Melon Real Melon är en barnhjälm med vattenmelonmönster för barn mellan 3 och 7 år, i storlek XXS/S (46–52 cm).",
 passar=["Barn mellan 3 och 7 år","Barn som behöver en hjälm som går att justera i storlek (Spin Dial och tre tjocklekar på stoppningen)","Dig som vill kunna öppna och stänga hjälmen med en hand (Fidlock)"],
 spec=["Stoppning: tre olika tjocklekar, CoolMax-stoppning som tål maskintvätt i 30 grader","Skal: polykarbonat (yttre), EPS (inre)","Ventilation: 12 ventilationsöppningar (MACS-system)","Spänne: Fidlock, magnetiskt, går att öppna och stänga med en hand","Storlek: XXS/S, 46–52 cm (3 till 7 år)","Tillbehör: vintertäcke, tillval","Justering: Spin Dial","Vikt: under 300 g"],
 faq=[("Hur justerar jag hjälmen?","Med Spin Dial-hjulet baktill på hjälmen. Stoppningen följer med i tre olika tjocklekar.")], marke=None,
 motivering="Engelsk källa översatt. Märkesmission, \"extra-safe\", \"skyddar\" och tillverkarens land i parentes utelämnas.",
 att_bekrafta=["Ingen säkerhetsstandard (till exempel EN 1078) nämns i källan, så texten påstår ingen.","Källan anger \"Made by Melon (Germany)\". Ursprung utelämnas.","Om vintertäcket säljs separat framgår inte."])

